            {value, rest} = Protox.Decode.parse_int64(bytes)
            msg = %{msg | ephemeralSettingTimestamp: value}
            parse_key_value(rest, msg)

          <<"H", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | ephemeralExpiration: value}
            parse_key_value(rest, msg)

          <<"H", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_uint32(bytes)
            msg = %{msg | ephemeralExpiration: value}
            parse_key_value(rest, msg)

          <<"@", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value != 0
            msg = %{msg | endOfHistoryTransfer: value}
            parse_key_value(rest, msg)

          <<"@", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_bool(bytes)
            msg = %{msg | endOfHistoryTransfer: value}
            parse_key_value(rest, msg)

          <<"8", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value != 0
            msg = %{msg | readOnly: value}
            parse_key_value(rest, msg)

          <<"8", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_bool(bytes)
            msg = %{msg | readOnly: value}
            parse_key_value(rest, msg)

          <<"0", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | unreadCount: value}
            parse_key_value(rest, msg)

          <<"0", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_uint32(bytes)
            msg = %{msg | unreadCount: value}
            parse_key_value(rest, msg)

          <<"(", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | lastMsgTimestamp: value}
            parse_key_value(rest, msg)

          <<"(", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_uint64(bytes)
            msg = %{msg | lastMsgTimestamp: value}
            parse_key_value(rest, msg)

          <<"\"", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | oldJID: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"\x1A", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | newJID: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"\x12", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | messages: [
                  WAWebProtobufsHistorySync.HistorySyncMsg.decode!(delimited)
                  | :erlang.map_get(:messages, msg)
                ]
            }

            parse_key_value(rest, msg)

          <<"\n", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | ID: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<bytes::binary>> ->
            {tag, wire_type, rest} = Protox.Decode.parse_key(bytes)
            {value, rest} = Protox.Decode.parse_unknown(tag, wire_type, rest)
            msg = %{msg | __uf__: [value | :erlang.map_get(:__uf__, msg)]}
            parse_key_value(rest, msg)
        end
      end
    )
  )

  (
    @spec unknown_fields(struct()) :: [{non_neg_integer(), Protox.Types.tag(), binary()}]
    def unknown_fields(msg), do: msg.__uf__

    @spec unknown_fields_name() :: :__uf__
    def unknown_fields_name(), do: :__uf__

    @spec clear_unknown_fields(struct) :: struct
    def clear_unknown_fields(msg), do: struct!(msg, __uf__: [])
  )

  (
    @spec default(atom()) ::
            {:ok, Protox.Scalar.scalar_default_value_type()}
            | {:error, :no_such_field | :no_default_value}
    def default(field_name), do: Protox.MessageSchema.default(@schema, field_name)
  )
end
